Translate("zhCN", "frayfeather-highlands", {
	title = "乱羽高地",
	sections = {
		{
			title = "概述",
			text = [=[乱羽高地在{link:feralas}菲拉斯{/link}南部隆起，紧邻{link:high-wilderness}高原荒野{/link}。它因在此筑巢的野生角鹰兽而得名，从年轻的雄鹿翼到年老的族长都有。角鹰兽长久以来都是{link:night-elves}暗夜精灵{/link}忠诚而坚定的朋友，因此{link:camp-mojache}莫沙彻营地{/link}的{link:trolls}巨魔{/link}猎杀这些野生角鹰兽，以夺取它们灵魂的力量。]=],
		},
	},
})

Translate("zhCN", "grimtotem-compound", {
	title = "恐怖图腾营地",
	sections = {
		{
			title = "概述",
			text = [=[恐怖图腾营地是{link:grimtotem-clan}恐怖图腾{/link}{link:tauren}牛头人{/link}在东部森林中的一座营地，位于{link:camp-mojache}莫沙彻营地{/link}以西。营地里的博物学者、掠夺者和萨满一直在捕捉{link:feralas}菲拉斯{/link}的精灵龙——精灵飞龙，并把它们关在竹笼里。没有人知道他们要用这些精灵龙做什么。两名{link:night-elves}暗夜精灵{/link}在上方的山脊上监视着营地。莫沙彻的{link:horde}部落{/link}得知恐怖图腾来到此地后，悬赏收购他们的角。]=],
		},
	},
})

Translate("zhCN", "lariss-pavilion", {
