Translate("zhCN", "woodpaw-hills", {
	title = "木爪岭",
	aliases = { "木爪巢穴" },
	sections = {
		{
			title = "概述",
			text = [=[木爪岭位于{link:camp-mojache}莫沙彻营地{/link}以南，木爪族群的{link:gnolls}豺狼人{/link}在这里遍布营地和巢穴。多年来，他们对营地的袭击只是一种骚扰。近来他们却变得狂乱起来。他们自己的作战计划揭示了原因：他们大部分的力量都转向了南方，对抗{link:the-writhing-deep}痛苦深渊{/link}的虫类，而且正在节节败退。两线作战让他们走投无路。]=],
