Translate("zhCN", "the-writhing-deep", {
	title = "痛苦深渊",
	sections = {
		{
			title = "概述",
			text = [=[痛苦深渊是{link:feralas}菲拉斯{/link}遥远东南部的一座虫巢。这里的地面扭曲成土丘和隧道，到处都是祖卡什：刺蝎、黄蜂、工虫和掘地虫。{link:darnassus}达纳苏斯{/link}和{link:orgrimmar}奥格瑞玛{/link}的学者都称它们为{link:qiraji}异种蝎{/link}，是{link:silithus}希利苏斯{/link}虫群的同类。它们把俘虏活活封在硬化的黏液荚囊中。它们当中有一个名为{link:stinglasher}毒刺鞭笞者{/link}的庞然大物，周身笼罩着一种其弱小同类所没有的光环，在巢穴中游走。]=],
		},
	},
})

Translate("zhCN", "shandris-feathermoon", {
	title = "珊蒂斯·羽月",
	subtitle = "哨兵部队将军",
	found = "羽月要塞，主营地内",
	hint = "去西海岸外的岛屿要塞中寻找哨兵的将军。",
	allegiance = "哨兵 · 达纳苏斯",
	aliases = { "珊蒂斯", "羽月将军" },
	sections = {
		{
			title = "概述",
			text = [=[珊蒂斯·羽月是{link:sentinels}哨兵{/link}部队的将军，是{link:tyrande-whisperwind}泰兰德·语风{/link}之剑，也是{link:night-elves}暗夜精灵{/link}的首席战士。她并不在{link:darnassus}达纳苏斯{/link}发号施令。她把驻地设在{link:feralas}菲拉斯{/link}海岸外一座岛上的{link:feathermoon-stronghold}羽月要塞{/link}，位于她的族人仍在守护的土地的南缘。她说话干脆，言辞简短；那些为她效力出色的人会得到感谢和报酬，然后再次被派出去。]=],
		},
		{
			title = "意义",
			text = [=[{link:sentinels}哨兵{/link}是一个民族的军队，而这个民族在这个时代本不该需要军队。自{link:third-war}第三次战争{/link}以来，她们一直在{link:ashenvale}灰谷{/link}和{link:stonetalon-mountains}石爪山脉{/link}与{link:horde}部落{/link}作战，而珊蒂斯在整个{link:kalimdor}卡利姆多{/link}坚守着这条防线。{link:feralas}菲拉斯{/link}是她对一个更大问题的回答：战争结束时，荒野世界还能剩下什么？她南下是为了不让大陆上最后的绿色土地落入部落之手，而她决心守住它们。

她的故事可以追溯到比当今任何战争都更久远的时代。据说，{link:war-of-the-ancients}上古战争{/link}撕裂她的世界时，她还是个孩子，一个被年轻的女祭司{link:tyrande-whisperwind}泰兰德{/link}收养的孤儿。]=],
		},
		{
			title = "事迹",
			text = [=[• 她率领{link:sentinels}哨兵{/link}远征军进入{link:feralas}菲拉斯{/link}，并建立了{link:feathermoon-stronghold}羽月要塞{/link}。
• 怒冠{link:naga}纳迦{/link}聚集在{link:ruins-of-solarsal}索兰萨尔废墟{/link}时，她派出斥候前去查探，并将对付纳迦的战事交给了她的副手{link:latronicus-moonspear}拉托尼库斯·月矛{/link}。
• 她拒绝将全部兵力投入对纳迦的作战，以免要塞向{link:horde}部落{/link}或更可怕的东西敞开大门。
• 她将祖卡什虫巢的消息送往{link:darnassus}达纳苏斯{/link}，并将{link:raschal-the-courier}信使拉斯卡尔{/link}的报告抄本送给{link:temple-of-the-moon}月神殿{/link}的女祭司格拉希娜·灵风。
• 德鲁伊{link:quintis-jonespyre}奎恩提斯{/link}将她与守护会一同列为质疑大德鲁伊对晨光麦之渴求的同僚。]=],
		},
		{
			title = "未载之事",
			text = [=[迄今写成的编年史都没有记载珊蒂斯何时成为将军，也没有记载她在{link:third-war}第三次战争{/link}中做了什么。关于她童年的故事来自{link:war-of-the-ancients}上古战争{/link}的史书，而非出自她本人之口。]=],
		},
	},
	chapters = {
		{
			title = "温热的石头",
			hint = "搜索将军所在岛屿南端的古老废墟。",
			text = [=[珊蒂斯原以为{link:ruins-of-solarsal}索兰萨尔废墟{/link}空无一物。{link:naga}纳迦{/link}大批涌入时，她起初以为这是进攻的开端，但她并不确定。传回的报告描述了一座比废墟更新的凉亭、无人能读的符文，以及摸上去温热的石头。她称之为令人不安。无论纳迦意欲何为，她现在知道，他们打算留下来。]=],
		},
		{
			title = "对抗怒冠",
			hint = "响应将军对抗纳迦的号召。",
			text = [=[珊蒂斯像一位将军应当做的那样权衡此事。她想用手中的每一把利刃打击{link:naga}纳迦{/link}。她也清楚，一座空虚的要塞会招来什么。最终，她把任务交给了监视纳迦最久的{link:latronicus-moonspear}拉托尼库斯{/link}，自己则继续关注更广阔的战局。]=],
		},
		{
			title = "异种蝎的崛起",
			hint = "因救回信使而接受将军的感谢。",
			text = [=[{link:raschal-the-courier}拉沙尔{/link}从{link:the-writhing-deep}痛苦深渊{/link}活着回来时，珊蒂斯亲自感谢了救他的人。随后，她立刻转向他的报告。把活着的精灵封进荚囊的虫类，不是一座要塞能独自应对的事。她将报告送往{link:darnassus}达纳苏斯{/link}，并将一份抄本送给一位了解这类生物的女祭司，祈愿艾露恩庇佑他们所有人。]=],
		},
	},
	mentions = {
		{ text = "{link:ruins-of-solarsal}索兰萨尔废墟{/link}" },
		{ text = "返回{link:feathermoon-stronghold}羽月要塞{/link}" },
		{ text = "对抗怒冠" },
		{ text = "英雄的欢迎" },
		{ text = "{link:qiraji}异种蝎{/link}的崛起" },
		{ text = "琼斯派尔的请求，其中将她列为守护会的一员" },
	},
	bonds = {
		{ id = "tyrande-whisperwind", name = "泰兰德·语风", note = "她的大祭司" },
		{ id = "latronicus-moonspear", name = "拉托尼库斯·月矛", note = "她的副手" },
		{ id = "ginro-hearthkindle", name = "基恩诺·火花", note = "为她寻找失踪的信使" },
		{ id = "quintis-jonespyre", name = "奎恩提斯", note = "她在守护会中的同僚" },
		{ id = "raschal-the-courier", name = "信使拉斯卡尔", note = "她的信使" },
		{ id = "hadoken-swiftstrider", name = "哈杜肯·迅蹄", note = "据守东部的部落营地" },
	},
})

Translate("zhCN", "latronicus-moonspear", {
