			hint = "将纳迦遗物带给羽月的学者。",
			text = [=[他请人把遗物带给他的妻子维斯蒂娅，他称她是任何地方最出色的学者。他需要知道那是什么。他怀疑，{link:naga}纳迦{/link}也想知道。]=],
