Translate("zhCN", "ginro-hearthkindle", {
	title = "基恩诺·火花",
	subtitle = "羽月的搜寻者",
	found = "羽月要塞，他的住处",
	hint = "找到那位不肯停止寻找失踪信使的哨兵。",
	allegiance = "哨兵 · 羽月要塞",
	aliases = { "基恩诺", "金" },
	sections = {
		{
			title = "概述",
			text = [=[基恩诺·火花是{link:feathermoon-stronghold}羽月要塞{/link}的一名士兵，他不肯放弃一位朋友。{link:raschal-the-courier}信使拉斯卡尔{/link}在前往{link:thalanaar}萨兰纳尔{/link}的路上失踪后，基恩诺每天都到荒野中寻找他，每晚回来时却只带回{link:gnolls}豺狼人{/link}的牙齿。即使要塞已宣布拉沙尔失踪，他仍在继续寻找。]=],
		},
		{
			title = "意义",
			text = [=[基恩诺的搜寻揭开了{link:feralas}菲拉斯{/link}最严重的危险。搜寻者们追踪一名失踪的信使，发现了祖卡什虫巢，这是南方{link:qiraji}异种蝎{/link}在这片土地上出现的第一个迹象。]=],
		},
		{
			title = "事迹",
			text = [=[• 他日复一日独自寻找{link:raschal-the-courier}拉沙尔{/link}。
• 他把信使的匕首送到德鲁伊{link:quintis-jonespyre}奎恩提斯{/link}那里，请他通过触摸来解读，并以免去一笔牌局赌债作为报酬。
• 德鲁伊的幻象指向木爪营地之后，他力主直接进攻。
• 他将拉沙尔的救援者带到{link:shandris-feathermoon}珊蒂斯·羽月{/link}面前。]=],
		},
	},
	chapters = {
		{
			title = "残骸",
			hint = "在菲拉斯海岸搜寻信使的船。",
			text = [=[{link:raschal-the-courier}拉沙尔{/link}原本打算沿海岸划船南下，再穿越{link:feralas}菲拉斯{/link}南部，以避开{link:horde}部落{/link}的营地。人们发现他的船已经沉没，船身破裂，侧面仍印着要塞的徽记。船下的泥中躺着他的匕首。水中的某种东西几乎将船拦腰折断。]=],
		},
		{
			title = "匕首的启示",
			hint = "了解信使的匕首记住了什么。",
			text = [=[{link:quintis-jonespyre}昆提斯{/link}握着匕首，看到{link:raschal-the-courier}拉沙尔{/link}背着两个包裹深入内陆，遇见了木爪{link:gnolls}豺狼人{/link}，然后惊恐地回到船上。拉沙尔并不害怕豺狼人能做的任何事。是别的东西吓坏了他，严重到他根本没有看到身后升起的海水。基恩诺这时明白，他寻找的不是一具尸体。]=],
		},
